package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.iteration.CooperativeCancellation;
import org.eclipse.rdf4j.common.iteration.IterationWrapper;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.SailException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Query timeouts push {@link CooperativeCancellation#requestCancellation()} down from the result wrapper, so every LMDB
 * result layer must forward it to the iteration doing the work.
 */
class LmdbCooperativeCancellationPropagationTest {

	@Test
	void statementResultForwardsCancellationToItsSource(@TempDir Path dataDir) {
		AtomicInteger sourceCancellations = new AtomicInteger();
		LmdbStore store = new LmdbStore(dataDir.toFile()) {
			@Override
			protected NotifyingSailConnection getConnectionInternal() throws SailException {
				return new LmdbStoreConnection(this) {
					@Override
					protected CloseableIteration<? extends Statement> getStatementsInternal(Resource subj, IRI pred,
							Value obj, boolean includeInferred, Resource... contexts) throws SailException {
						return new IterationWrapper<Statement>(super.getStatementsInternal(subj, pred, obj,
								includeInferred, contexts)) {
							@Override
							public boolean requestCancellation() {
								sourceCancellations.incrementAndGet();
								return true;
							}
						};
					}
				};
			}
		};
		store.init();
		try {
			var values = SimpleValueFactory.getInstance();
			try (SailConnection seed = store.getConnection()) {
				seed.begin();
				seed.addStatement(values.createIRI("urn:cancel:s"), values.createIRI("urn:cancel:p"),
						values.createLiteral("o"));
				seed.commit();
			}
			try (SailConnection connection = store.getConnection();
					CloseableIteration<? extends Statement> result = connection.getStatements(null, null, null,
							false)) {
				CooperativeCancellation cancellable = assertInstanceOf(CooperativeCancellation.class, result,
						"public LMDB results must accept cooperative cancellation");
				assertTrue(cancellable.requestCancellation(),
						"the request must reach the source that does the work and report acceptance");
				assertEquals(1, sourceCancellations.get(), "the source must receive the request exactly once");
			}
		} finally {
			store.shutDown();
		}
	}
}
